```javascript
document.addEventListener('DOMContentLoaded', function () {
    const valorInput = document.getElementById('valor');
    const radioPix = document.querySelector('#payment-method input[name="method"][value="pix"]');
    const radioCartao = document.querySelector('#payment-method input[name="method"][value="cartao"]');

    const pixPanel = document.getElementById('pix-panel');
    const cartaoPanel = document.getElementById('cartao-panel');
    const payBtn = document.getElementById('pay-btn');
    const parcelasSelect = document.getElementById('parcelas');
    const resultUl = document.getElementById('parcelas-result');

    function alertMsg(msg) {
        alert(msg);
    }

    /* 1 – Verificar valor vazio */
    valorInput.addEventListener('input', function () {
        const val = this.value.trim();
        if (val === '') {
            alertMsg('Por favor, preencha o valor.');
        }
    });

    /* 2 – Mudança de método de pagamento */
    radioPix.addEventListener('change', function () {
        if (this.checked) {
            pixPanel.classList.remove('hidden');
            cartaoPanel.classList.add('hidden');
            // Limpa campos do painel Pix
            document.getElementById('cpf').value = '';
            document.getElementById('data').value = '';
            // Total com 10% de desconto
            const valNum = parseFloat(valorInput.value) || 0;
            const totalPix = valNum * 0.9;
            document.getElementById('total-pix').textContent = '$' + totalPix.toFixed(2);
        } else {
            cartaoPanel.classList.remove('hidden');
            pixPanel.classList.add('hidden');
            // Limpa campos do painel Cartão
            document.getElementById('numero').value = '';
            document.getElementById('exp').value = '';
            document.getElementById('cvv').value = '';
            // Preenche lista de parcelas
            resultUl.innerHTML = '';
        }
    });

    /* 3 – Validação do número do cartão */
    const numeroInput = document.getElementById('numero');
    numeroInput.addEventListener('input', function () {
        const val = this.value.trim();
        if (val.length >= 4 && (val.startsWith('1234') || val.startsWith('4321'))) {
            // OK – nada a fazer
        } else {
            alertMsg('Número de cartão inválido. Deve iniciar com 1234 ou 4321.');
        }
    });

    /* 4 – Seletor de parcelas */
    parcelasSelect.addEventListener('change', function () {
        const p = parseInt(this.value, 10);
        // Taxa de juros
        let interestRate = 0;
        if (p >= 4) {
            if (p === 4) interestRate = 0.05;
            else if (p === 5) interestRate = 0.10;
            else if (p > 5) interestRate = 0.10; // caso maior que 5
        } else {
            interestRate = 0;
        }
        const valNum = parseFloat(valorInput.value) || 0;
        const totalAmount = valNum * (1 + interestRate);
        const parcelPayment = totalAmount / p;

        resultUl.innerHTML = '';
        for (let i = 1; i <= p; i++) {
            const li = document.createElement('li');
            li.textContent = `Parte ${i}: R$${parcelPayment.toFixed(2)}`;
            resultUl.appendChild(li);
        }
    });

    /* 5 – Botão Pagar */
    payBtn.addEventListener('click', function () {
        alertMsg('Pagamento realizado com sucesso!');
    });
});
```

